// ======================================================
// CONFIGURACION DE CAMPAÑAS TIAN MOTORS (company 230, grupo 791)
// Cada campaña: id en campaigns-api y qué dato va en cada variable del template.
// Para sumar una campaña nueva, agregala acá.
// ======================================================
const CAMPANAS = {
  bienvenida: { id: 4864, nombre: 'Bienvenida', vars: { '1': 'marca',  '2': 'administrativa' } },
  unidad_asignada: { id: 4865, nombre: 'Unidad Asignada', vars: { '1': 'nombre', '2': 'marca' } },
  unidad_patentada: { id: 4866, nombre: 'Unidad Patentada', vars: { '1': 'marca',  '2': 'modelo' } },
  seguros: { id: 4867, nombre: 'Seguros', vars: { '1': 'nombre', '2': 'marca' } },
  accesorios: { id: 4868, nombre: 'Accesorios', vars: { '1': 'nombre', '2': 'marca' } },
};

// Estado de Pilot (ADMIN_FILE_STATUS) -> campaña. Igual que el webhook viejo de Robayna.
// Los estados se normalizan: "BANDEJA DE ENTRADA", "Bandeja de entrada" y "bandeja_de_entrada" son lo mismo.
const ESTADOS = {
  bandeja_de_entrada: 'bienvenida',
  bienvenida:         'bienvenida',
  unidad_asignada:    'unidad_asignada',
  unidad_patentada:   'unidad_patentada',
  seguros:            'seguros',
  accesorios:         'accesorios',
  // calendarizacion_de_entrega: sin campaña en el módulo de campañas todavía
};

const SENDER_PHONE = '5491166265024';
const COMPANY_ID = '230';

const body = $json.body || {};
const pick = (...keys) => {
  for (const k of keys) {
    const v = body[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim().replace(/\s+/g, ' ');
  }
  return '';
};
const normClave = (s) => s.normalize('NFD').replace(/[̀-ͯ]/g, '')
  .toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');

// Manda el campo ID si viene; si no, el estado del legajo (como el webhook viejo).
const claveId = normClave(pick('ID', 'id', 'campana', 'campaña', 'campaign', 'flujo', 'evento'));
const claveEstado = normClave(pick('estado', 'Estado', 'status'));
const clave = claveId || claveEstado;
const campKey = ESTADOS[clave] || (CAMPANAS[clave] ? clave : '');

// Telefono argentino -> 549 + area + numero. Si no es valido, vacío (no se envía).
const norm = (raw) => {
  let d = String(raw ?? '').replace(/\D/g, '');
  if (!d || /^0+$/.test(d)) return '';
  d = d.replace(/^00/, '');
  if (d.startsWith('54')) d = d.slice(2);
  if (d.startsWith('9')) d = d.slice(1);
  if (d.startsWith('0')) d = d.slice(1);
  if (d.length === 12) {
    const pos = d.startsWith('11') ? [2] : [3, 4, 2];
    for (const p of pos) {
      if (d.substr(p, 2) === '15') { d = d.slice(0, p) + d.slice(p + 2); break; }
    }
  }
  return d.length === 10 ? '549' + d : '';
};

const datos = {
  nombre:         pick('cliente_nombre', 'nombre', 'Nombre', 'first_name'),
  marca:          pick('marca', 'Marca', 'brand'),
  modelo:         pick('modelo', 'Modelo', 'model', 'producto'),
  administrativa: pick('administrativa', 'Administrativa', 'vendedor', 'Vendedor', 'asesor'),
  guid:           pick('GUID', 'guid', 'lead_guid'),
};
const telefono = norm(pick('cliente_cel', 'Telefono', 'telefono', 'celular')) || norm(pick('cliente_tel', 'phone'));

const camp = CAMPANAS[campKey];
const variables = {};
const faltan = [];
if (camp) {
  for (const [n, campo] of Object.entries(camp.vars)) {
    variables[n] = datos[campo];
    if (!datos[campo]) faltan.push(campo);
  }
}
if (!telefono) faltan.push('telefono valido');

let motivo = '';
if (!camp) motivo = `Estado/campaña sin campaña asignada: "${clave || '(vacío)'}". Válidos: ${Object.keys(ESTADOS).join(', ')}`;
else if (faltan.length) motivo = `Faltan datos para ${camp.nombre}: ${faltan.join(', ')}`;

return {
  json: {
    enviar: !motivo,
    motivo,
    estado_recibido: pick('estado', 'Estado', 'status'),
    campana: camp ? camp.nombre : clave,
    campaign_id: camp ? camp.id : null,
    telefono,
    variables,
    company_id: COMPANY_ID,
    request: {
      phone_number: telefono,
      sender_phone: SENDER_PHONE,
      destination_country: 'AR',
      enqueue_if_no_credit: true,
      daily_envio: true,
      ...(datos.guid ? { crm_lead_guid: datos.guid } : {}),
      variables,
    },
  },
};

